// The demo deployment: invite-only Cognito, API on Lambda (streaming), SPA on S3 + CloudFront,
// DynamoDB plans with TTL and a daily purge, the API key in Secrets Manager. Nothing here holds a
// secret value: the API key secret is created empty-random and its value is put by the deploy job;
// the CloudFront origin secret is generated by Secrets Manager and reaches CloudFront only as a
// dynamic reference, resolved by CloudFormation at deploy time.
import {
  CfnOutput,
  CfnResource,
  Duration,
  Fn,
  RemovalPolicy,
  Stack,
  type StackProps,
  aws_budgets as budgets,
  aws_cloudfront as cloudfront,
  aws_cloudfront_origins as origins,
  aws_cognito as cognito,
  aws_dynamodb as dynamodb,
  aws_iam as iam,
  aws_events as events,
  aws_events_targets as targets,
  aws_lambda as lambda,
  aws_logs as logs,
  aws_s3 as s3,
  aws_s3_deployment as s3deploy,
  aws_secretsmanager as secretsmanager,
} from "aws-cdk-lib";
import type { Construct } from "constructs";

export const SECRET_NAME = "future-pkg/anthropic-api-key";
/** Header CloudFront adds to every API request; the API refuses requests without it (main.py). */
export const ORIGIN_HEADER = "x-origin-verify";
// AWS Lambda Web Adapter (Apache-2.0, awslabs): runs the FastAPI app unchanged and streams responses.
const WEB_ADAPTER_LAYER = "arn:aws:lambda:us-east-1:753240598075:layer:LambdaAdapterLayerX86:30";

export interface DemoStackProps extends StackProps {
  /** Directory with the packaged API (scripts/package_lambda.sh). */
  lambdaDir: string;
  /** The built SPA (web/dist). */
  webDir: string;
  modelFast: string;
  modelMain: string;
  /** Cap on concurrent API executions, which bounds model spend under a flood. Default 5. */
  apiConcurrency?: number;
  /** Where the monthly cost budget emails its alerts. No address, no budget. */
  budgetEmail?: string;
  /** Monthly budget in USD for the alerts. Default 20. */
  monthlyBudgetUsd?: number;
}

export class DemoStack extends Stack {
  constructor(scope: Construct, id: string, props: DemoStackProps) {
    super(scope, id, props);

    // ---------- storage ----------
    const plans = new dynamodb.Table(this, "Plans", {
      partitionKey: { name: "id", type: dynamodb.AttributeType.STRING },
      billingMode: dynamodb.BillingMode.PAY_PER_REQUEST,
      timeToLiveAttribute: "expires_at",
      removalPolicy: RemovalPolicy.DESTROY,
    });

    // Access requests (email, optional name, reason) expire after 7 days; rate counters after 2 hours.
    const access = new dynamodb.Table(this, "AccessRequests", {
      partitionKey: { name: "id", type: dynamodb.AttributeType.STRING },
      billingMode: dynamodb.BillingMode.PAY_PER_REQUEST,
      timeToLiveAttribute: "expires_at",
      removalPolicy: RemovalPolicy.DESTROY,
    });
    // Sparse: only request items have a status, so the form counts pending requests with a query.
    access.addGlobalSecondaryIndex({
      indexName: "by-status",
      partitionKey: { name: "status", type: dynamodb.AttributeType.STRING },
    });

    const apiKey = new secretsmanager.Secret(this, "AnthropicKey", {
      secretName: SECRET_NAME,
      description: "Anthropic API key for the coach demo; value is put by the deploy job",
      removalPolicy: RemovalPolicy.DESTROY,
    });

    // Shared between CloudFront and the API only. Generated here, never written down.
    const originSecret = new secretsmanager.Secret(this, "OriginVerify", {
      description: "Header value CloudFront sends the API, so the function URL can't be used directly",
      generateSecretString: { passwordLength: 48, excludePunctuation: true },
      removalPolicy: RemovalPolicy.DESTROY,
    });

    // ---------- auth: invite-only coaches ----------
    const pool = new cognito.UserPool(this, "Coaches", {
      userPoolName: "future-pkg-coaches",
      selfSignUpEnabled: false,
      signInAliases: { email: true },
      autoVerify: { email: true },
      featurePlan: cognito.FeaturePlan.LITE,
      passwordPolicy: {
        minLength: 12,
        requireLowercase: true,
        requireUppercase: true,
        requireDigits: true,
        requireSymbols: false,
        tempPasswordValidity: Duration.days(7),
      },
      accountRecovery: cognito.AccountRecovery.NONE,
      customAttributes: { coach_id: new cognito.StringAttribute({ minLen: 1, maxLen: 64, mutable: true }) },
      userInvitation: {
        emailSubject: "Your coach workspace demo invite",
        emailBody:
          "You're invited to the coach decision support demo (synthetic data only). " +
          "Sign in with {username} and the temporary password {####}, then choose your own.",
      },
      removalPolicy: RemovalPolicy.DESTROY,
    });
    const client = pool.addClient("Web", {
      authFlows: { userPassword: true },
      // The SPA signs in through the Cognito API only; no hosted UI or OAuth flows.
      disableOAuth: true,
      generateSecret: false,
      preventUserExistenceErrors: true,
      idTokenValidity: Duration.hours(1),
      accessTokenValidity: Duration.hours(1),
      refreshTokenValidity: Duration.hours(8),
      readAttributes: new cognito.ClientAttributes()
        .withStandardAttributes({ email: true })
        .withCustomAttributes("coach_id"),
      // Coaches can't write their own coach_id (only an admin sets it, so a token can't be re-scoped)
      // or their email. An empty list would mean "every standard attribute" to Cognito, so the
      // client may write one attribute nothing reads.
      writeAttributes: new cognito.ClientAttributes().withStandardAttributes({ nickname: true }),
    });

    // Admins approve access requests and manage reviewer accounts. Membership is granted only by
    // AWS (this stack, or the console), never by the app.
    const admins = new cognito.CfnUserPoolGroup(this, "Admins", {
      userPoolId: pool.userPoolId,
      groupName: "admin",
      description: "Demo admins: approve access requests, invite and disable reviewers",
    });
    // The first admin is added by the owner with the AWS CLI (docs/deploy.md), not by this stack: a
    // custom resource would log the admin's email in its provider's CloudWatch logs.

    // ---------- API ----------
    const apiLogs = new logs.LogGroup(this, "ApiLogs", {
      retention: logs.RetentionDays.TWO_WEEKS,
      removalPolicy: RemovalPolicy.DESTROY,
    });
    const api = new lambda.Function(this, "Api", {
      runtime: lambda.Runtime.PYTHON_3_12,
      architecture: lambda.Architecture.X86_64,
      code: lambda.Code.fromAsset(props.lambdaDir),
      handler: "run.sh",
      memorySize: 1769,
      timeout: Duration.seconds(60),
      reservedConcurrentExecutions: props.apiConcurrency ?? 5,
      layers: [lambda.LayerVersion.fromLayerVersionArn(this, "WebAdapter", WEB_ADAPTER_LAYER)],
      logGroup: apiLogs,
      environment: {
        AWS_LAMBDA_EXEC_WRAPPER: "/opt/bootstrap",
        AWS_LWA_INVOKE_MODE: "response_stream",
        AWS_LWA_READINESS_CHECK_PATH: "/healthz",
        PORT: "8080",
        AUTH_MODE: "cognito",
        COGNITO_USER_POOL_ID: pool.userPoolId,
        COGNITO_CLIENT_ID: client.userPoolClientId,
        PLAN_TABLE: plans.tableName,
        ACCESS_TABLE: access.tableName,
        // Salt for hashing client addresses in rate counters: the stack's own GUID, not a secret.
        RATE_SALT: Fn.select(2, Fn.split("/", this.stackId)),
        ANTHROPIC_SECRET_ID: apiKey.secretName,
        ORIGIN_SECRET_ID: originSecret.secretArn,
        LLM_MODEL_FAST: props.modelFast,
        LLM_MODEL_MAIN: props.modelMain,
        AS_OF_DATE: "2026-06-04",
        DATA_DIR: "/var/task/data",
        KG_DIR: "/var/task/kg",
        FIXTURES_DIR: "/var/task/fixtures",
      },
    });
    plans.grantReadWriteData(api);
    access.grantReadWriteData(api);
    apiKey.grantRead(api);
    originSecret.grantRead(api);
    api.addToRolePolicy(
      new iam.PolicyStatement({
        actions: [
          "cognito-idp:AdminCreateUser",
          "cognito-idp:AdminDisableUser",
          "cognito-idp:AdminEnableUser",
          // Read-only: the API refuses a disabled account's token within a minute (auth.py).
          "cognito-idp:AdminGetUser",
          "cognito-idp:ListUsers",
          "cognito-idp:ListUsersInGroup",
        ],
        resources: [pool.userPoolArn],
      }),
    );
    // The URL has no IAM auth (CloudFront would have to sign POST bodies), so the API itself refuses
    // any request without CloudFront's origin header; /healthz returns only {"status":"ok"}.
    const apiUrl = api.addFunctionUrl({
      authType: lambda.FunctionUrlAuthType.NONE,
      invokeMode: lambda.InvokeMode.RESPONSE_STREAM,
    });

    // ---------- purge: daily, deletes every plan drafted more than 12 hours ago and every expired
    // access request and rate counter (TTL is the backstop) ----------
    const purge = new lambda.Function(this, "Purge", {
      runtime: lambda.Runtime.PYTHON_3_12,
      handler: "index.handler",
      timeout: Duration.minutes(5),
      code: lambda.Code.fromInline(PURGE_CODE),
      environment: { PLAN_TABLE: plans.tableName, ACCESS_TABLE: access.tableName },
      logGroup: new logs.LogGroup(this, "PurgeLogs", {
        retention: logs.RetentionDays.TWO_WEEKS,
        removalPolicy: RemovalPolicy.DESTROY,
      }),
    });
    plans.grantReadWriteData(purge);
    access.grantReadWriteData(purge);
    new events.Rule(this, "DailyPurge", {
      schedule: events.Schedule.rate(Duration.days(1)),
      targets: [new targets.LambdaFunction(purge)],
    });

    // ---------- web ----------
    const site = new s3.Bucket(this, "Site", {
      blockPublicAccess: s3.BlockPublicAccess.BLOCK_ALL,
      encryption: s3.BucketEncryption.S3_MANAGED,
      enforceSSL: true,
      removalPolicy: RemovalPolicy.DESTROY,
      autoDeleteObjects: true,
    });
    const headers = new cloudfront.ResponseHeadersPolicy(this, "Headers", {
      customHeadersBehavior: {
        customHeaders: [
          { header: "X-Robots-Tag", value: "noindex, nofollow, noarchive", override: true },
          {
            header: "Permissions-Policy",
            value: "camera=(), microphone=(), geolocation=(), payment=(), usb=(), interest-cohort=()",
            override: true,
          },
        ],
      },
      removeHeaders: ["server", "x-amz-server-side-encryption"],
      securityHeadersBehavior: {
        contentSecurityPolicy: {
          contentSecurityPolicy: [
            "default-src 'self'",
            "script-src 'self'",
            // No 'unsafe-inline': React and Recharts set styles through the DOM, which CSP allows.
            "style-src 'self'",
            "font-src 'self'",
            `connect-src 'self' https://cognito-idp.${this.region}.amazonaws.com`,
            "img-src 'self' data:",
            "frame-ancestors 'none'",
            "base-uri 'none'",
            "form-action 'self'",
          ].join("; "),
          override: true,
        },
        contentTypeOptions: { override: true },
        frameOptions: { frameOption: cloudfront.HeadersFrameOption.DENY, override: true },
        referrerPolicy: { referrerPolicy: cloudfront.HeadersReferrerPolicy.NO_REFERRER, override: true },
        strictTransportSecurity: {
          accessControlMaxAge: Duration.days(365),
          includeSubdomains: true,
          override: true,
        },
      },
    });
    // Runs at the edge before any API request reaches Lambda: requests without a bearer token are
    // answered here (so a flood of anonymous calls can't use up the API's concurrency), and the
    // viewer's address is written into X-Viewer-Ip, overwriting any copy the client sent.
    const apiGate = new cloudfront.Function(this, "ApiGate", {
      runtime: cloudfront.FunctionRuntime.JS_2_0,
      comment: "future-pkg: anonymous API calls stop at the edge; trusted viewer address",
      code: cloudfront.FunctionCode.fromInline(API_GATE_CODE),
    });
    const distribution = new cloudfront.Distribution(this, "Cdn", {
      comment: "future-pkg coach demo (synthetic data only)",
      defaultRootObject: "index.html",
      priceClass: cloudfront.PriceClass.PRICE_CLASS_100,
      defaultBehavior: {
        origin: origins.S3BucketOrigin.withOriginAccessControl(site),
        viewerProtocolPolicy: cloudfront.ViewerProtocolPolicy.REDIRECT_TO_HTTPS,
        responseHeadersPolicy: headers,
      },
      additionalBehaviors: {
        "/api/*": {
          origin: new origins.FunctionUrlOrigin(apiUrl, {
            readTimeout: Duration.seconds(60),
            // A dynamic reference: the template holds {{resolve:secretsmanager:...}}, not the value.
            customHeaders: { [ORIGIN_HEADER]: originSecret.secretValue.unsafeUnwrap() },
          }),
          viewerProtocolPolicy: cloudfront.ViewerProtocolPolicy.HTTPS_ONLY,
          allowedMethods: cloudfront.AllowedMethods.ALLOW_ALL,
          cachePolicy: cloudfront.CachePolicy.CACHING_DISABLED,
          originRequestPolicy: cloudfront.OriginRequestPolicy.ALL_VIEWER_EXCEPT_HOST_HEADER,
          responseHeadersPolicy: headers,
          functionAssociations: [
            { function: apiGate, eventType: cloudfront.FunctionEventType.VIEWER_REQUEST },
          ],
        },
      },
    });
    new s3deploy.BucketDeployment(this, "SiteFiles", {
      destinationBucket: site,
      distribution,
      distributionPaths: ["/*"],
      sources: [
        s3deploy.Source.asset(props.webDir),
        s3deploy.Source.jsonData("config.json", {
          authMode: "cognito",
          region: this.region,
          userPoolClientId: client.userPoolClientId,
        }),
      ],
      memoryLimit: 256,
    });

    // ---------- cost guard ----------
    if (props.budgetEmail) {
      new budgets.CfnBudget(this, "MonthlyBudget", {
        budget: {
          budgetName: "future-pkg-demo-monthly",
          budgetType: "COST",
          timeUnit: "MONTHLY",
          budgetLimit: { amount: props.monthlyBudgetUsd ?? 20, unit: "USD" },
        },
        notificationsWithSubscribers: [
          { threshold: 50, notificationType: "ACTUAL" },
          { threshold: 100, notificationType: "ACTUAL" },
          { threshold: 100, notificationType: "FORECASTED" },
        ].map((n) => ({
          notification: { ...n, comparisonOperator: "GREATER_THAN", thresholdType: "PERCENTAGE" },
          subscribers: [{ subscriptionType: "EMAIL", address: props.budgetEmail as string }],
        })),
      });
    }

    // ---------- log retention for CDK's own provider functions ----------
    // The bucket deployment and S3 auto-delete providers log to /aws/lambda/<name>,
    // which Lambda creates with no expiry. LogRetention sets 14 days on those groups, including
    // ones that already exist (its own function's group gets 1 day).
    const ownFunctions = new Set([api.node.defaultChild, purge.node.defaultChild]);
    const providers = this.node
      .findAll()
      .filter(
        (c): c is CfnResource =>
          c instanceof CfnResource && c.cfnResourceType === "AWS::Lambda::Function" && !ownFunctions.has(c),
      );
    providers.forEach((fn, i) => {
      new logs.LogRetention(this, `ProviderLogRetention${i}`, {
        logGroupName: Fn.join("", ["/aws/lambda/", fn.ref]),
        retention: logs.RetentionDays.TWO_WEEKS,
      });
    });

    // Outputs carry no secrets and no account id.
    new CfnOutput(this, "SiteUrl", { value: `https://${distribution.distributionDomainName}` });
    new CfnOutput(this, "UserPoolId", { value: pool.userPoolId });
  }
}

/** CloudFront Function (viewer request) for /api/*. Exported so the tests can run it. */
export const API_GATE_CODE = `
function handler(event) {
  var req = event.request;
  req.headers["x-viewer-ip"] = { value: event.viewer.ip };
  var open = req.method === "POST" && req.uri === "/api/access-requests";
  var auth = req.headers["authorization"];
  var bearer = auth && /^Bearer [A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+$/.test(auth.value);
  if (open || bearer) return req;
  return {
    statusCode: 401,
    statusDescription: "Unauthorized",
    headers: {
      "content-type": { value: "application/json" },
      "www-authenticate": { value: "Bearer" },
      "x-robots-tag": { value: "noindex, nofollow, noarchive" },
      "cache-control": { value: "no-store" }
    },
    body: { encoding: "text", data: '{"detail":"Sign in required"}' }
  };
}
`;

const PURGE_CODE = `
import os, time, boto3
ddb = boto3.resource("dynamodb")
DAY = 86400

def sweep(table, cutoff):
    deleted, kwargs = 0, {"ProjectionExpression": "id, expires_at"}
    while True:
        page = table.scan(**kwargs)
        with table.batch_writer() as batch:
            for item in page.get("Items", []):
                if int(item.get("expires_at", 0)) <= cutoff:
                    batch.delete_item(Key={"id": item["id"]})
                    deleted += 1
        if "LastEvaluatedKey" not in page:
            return deleted
        kwargs["ExclusiveStartKey"] = page["LastEvaluatedKey"]

def handler(event, context):
    now = int(time.time())
    # expires_at = drafted + 1 day, so expires_at <= now + 12 h means drafted over 12 hours ago.
    plans = sweep(ddb.Table(os.environ["PLAN_TABLE"]), now + DAY // 2)
    # Access requests (7 days) and rate counters (2 hours): anything past its expiry.
    access = sweep(ddb.Table(os.environ["ACCESS_TABLE"]), now)
    print(f"purged {plans} plans, {access} access items")
    return {"purged": plans, "access": access}
`;
